function textValue(value, fallback = "") {
  const text = repairText(value);
  return text || fallback;
}

function departmentLabel(postcode) {
  const digits = textValue(postcode).replace(/\s+/g, "");
  if (!digits) return "Vernon";
  if (digits.startsWith("20")) return "Corse";
  if (digits.startsWith("97") || digits.startsWith("98")) return `Dept. ${digits.slice(0, 3)}`;
  return `Dept. ${digits.slice(0, 2)}`;
}

function formatCount(value) {
  return Number(value || 0).toLocaleString("fr-FR");
}

function distanceMeters(from, to) {
  if (!from || !to) return null;
  const toRadians = value => value * Math.PI / 180;
  const earthRadius = 6371000;
  const deltaLat = toRadians(to.lat - from.lat);
  const deltaLng = toRadians(to.lng - from.lng);
  const startLat = toRadians(from.lat);
  const endLat = toRadians(to.lat);
  const a = Math.sin(deltaLat / 2) ** 2 + Math.cos(startLat) * Math.cos(endLat) * Math.sin(deltaLng / 2) ** 2;
  return 2 * earthRadius * Math.asin(Math.sqrt(a));
}

function isInsideVernonArea(location) {
  if (!location || !Number.isFinite(location.lat) || !Number.isFinite(location.lng)) {
    return false;
  }
  return distanceMeters(VERNON_CENTER, location) <= VERNON_FILTER_RADIUS_METERS;
}

function isVernonAreaAed(aed) {
  const city = textValue(aed?.city).toLowerCase();
  const postcode = textValue(aed?.postcode).replace(/\s+/g, "");
  const matchesVernonLabel = city.includes("vernon") || VERNON_POSTCODES.has(postcode);
  return matchesVernonLabel && isInsideVernonArea(aed);
}

function routeKeyFor(from, to) {
  const start = normaliseLatLngPoint(from);
  const end = normaliseLatLngPoint(to);
  if (!start || !end) return "";
  return `${start.lat.toFixed(4)},${start.lng.toFixed(4)}:${end.lat.toFixed(4)},${end.lng.toFixed(4)}`;
}

function formatDistance(meters) {
  if (!Number.isFinite(meters)) return "GPS off";
  if (meters < 1000) return `${Math.round(meters)} m`;
  const decimals = meters >= 10000 ? 0 : 1;
  return `${(meters / 1000).toFixed(decimals).replace(".", ",")} km`;
}

function formatDuration(minutes) {
  if (!Number.isFinite(minutes)) return "GPS off";
  if (minutes < 1) return "< 1 min";
  if (minutes < 60) return `${minutes} min`;
  const hours = Math.floor(minutes / 60);
  const remaining = minutes % 60;
  return `${hours} h ${String(remaining).padStart(2, "0")}`;
}

